import string

import pytest
from hypothesis import given, strategies as st

from solution import valid_date


# ---- Obviously-correct reference model derived strictly from SPEC ----

_DAYS_31 = {1, 3, 5, 7, 8, 10, 12}
_DAYS_30 = {4, 6, 9, 11}

def _max_day(month: int) -> int:
    if month == 2:
        return 29
    if month in _DAYS_31:
        return 31
    if month in _DAYS_30:
        return 30
    raise AssertionError("invalid month")


def reference(date) -> bool:
    # Rule 1: non-empty string; Rule 4: format mm-dd-yyyy (10 chars, digits + dashes)
    if not isinstance(date, str):
        return False
    if len(date) == 0:
        return False
    if len(date) != 10:
        return False
    if date[2] != "-" or date[5] != "-":
        return False
    m_s, d_s, y_s = date[:2], date[3:5], date[6:]
    if len(m_s) != 2 or len(d_s) != 2 or len(y_s) != 4:
        return False
    if not (m_s.isdigit() and d_s.isdigit() and y_s.isdigit()):
        return False
    m = int(m_s)
    d = int(d_s)
    # Rule 3
    if not 1 <= m <= 12:
        return False
    # Rule 2
    if not 1 <= d <= _max_day(m):
        return False
    return True


# ---- Explicit spec examples ----

def test_spec_example_march_valid():
    assert valid_date('03-11-2000') is True


def test_spec_example_month_15_invalid():
    assert valid_date('15-01-2012') is False


def test_spec_example_day_zero_invalid():
    assert valid_date('04-0-2040') is False


def test_spec_example_june_valid():
    assert valid_date('06-04-2020') is True


def test_spec_example_slash_separator_invalid():
    assert valid_date('06/04/2020') is False


# ---- Explicit boundary / rule tests ----

def test_empty_string_is_invalid():
    assert valid_date('') is False


def test_month_12_is_valid_december():
    # Catches 1 <= m <= 11 off-by-one (December wrongly rejected)
    assert valid_date('12-01-2000') is True
    assert valid_date('12-15-1999') is True
    assert valid_date('12-31-2000') is True


def test_month_boundaries_zero_and_thirteen_invalid():
    assert valid_date('00-15-2000') is False
    assert valid_date('13-15-2000') is False
    assert valid_date('00-00-0000') is False


def test_month_11_vs_12_vs_13():
    assert valid_date('11-30-2000') is True
    assert valid_date('12-30-2000') is True
    assert valid_date('13-30-2000') is False


def test_february_day_boundaries():
    assert valid_date('02-01-2000') is True
    assert valid_date('02-28-2000') is True
    assert valid_date('02-29-2000') is True
    assert valid_date('02-30-2000') is False
    assert valid_date('02-31-2000') is False
    assert valid_date('02-00-2000') is False


def test_thirty_day_months_reject_31():
    for m in ['04', '06', '09', '11']:
        assert valid_date(f'{m}-30-2000') is True
        assert valid_date(f'{m}-31-2000') is False
        assert valid_date(f'{m}-00-2000') is False
        assert valid_date(f'{m}-01-2000') is True


def test_thirtyone_day_months_accept_31():
    for m in ['01', '03', '05', '07', '08', '10', '12']:
        assert valid_date(f'{m}-31-2000') is True
        assert valid_date(f'{m}-32-2000') is False
        assert valid_date(f'{m}-00-2000') is False


def test_format_must_be_mm_dd_yyyy_with_dashes():
    assert valid_date('06-04-2020') is True
    assert valid_date('06/04/2020') is False
    assert valid_date('06.04.2020') is False
    assert valid_date('06 04 2020') is False
    assert valid_date('06-04/2020') is False
    assert valid_date('06/04-2020') is False


def test_format_requires_two_digit_month_day():
    # 'mm-dd-yyyy' means exactly 2/2/4 digits
    assert valid_date('6-04-2020') is False
    assert valid_date('06-4-2020') is False
    assert valid_date('6-4-2020') is False
    assert valid_date('06-04-20') is False
    assert valid_date('06-04-20200') is False


def test_non_digit_characters_invalid():
    assert valid_date('ab-cd-efgh') is False
    assert valid_date('0a-11-2000') is False
    assert valid_date('03-1b-2000') is False
    assert valid_date('03-11-20a0') is False
    assert valid_date('  -  -    ') is False


def test_length_not_ten_invalid():
    assert valid_date('03-11-200') is False
    assert valid_date('03-11-20000') is False
    assert valid_date('03-11-2000 ') is False
    assert valid_date(' 03-11-2000') is False


# ---- Property-based tests ----

@given(
    m=st.integers(min_value=1, max_value=12),
    d=st.integers(min_value=1, max_value=29),
    y=st.integers(min_value=0, max_value=9999),
)
def test_property_all_months_share_days_1_to_28_or_29(m, d, y):
    # Days 1..28 valid for every month; day 29 valid for every month per spec
    # (Feb max 29, all others >= 30). So formatted date must be True.
    s = f"{m:02d}-{d:02d}-{y:04d}"
    assert reference(s) is True
    assert valid_date(s) is True


@given(
    m=st.sampled_from([1, 3, 5, 7, 8, 10, 12]),
    y=st.integers(min_value=0, max_value=9999),
)
def test_property_31_day_months_accept_30_and_31_reject_32(m, y):
    y_s = f"{y:04d}"
    assert valid_date(f"{m:02d}-30-{y_s}") is True
    assert valid_date(f"{m:02d}-31-{y_s}") is True
    assert valid_date(f"{m:02d}-32-{y_s}") is False
    assert valid_date(f"{m:02d}-00-{y_s}") is False


@given(
    m=st.sampled_from([4, 6, 9, 11]),
    y=st.integers(min_value=0, max_value=9999),
)
def test_property_30_day_months_boundary(m, y):
    y_s = f"{y:04d}"
    assert valid_date(f"{m:02d}-30-{y_s}") is True
    assert valid_date(f"{m:02d}-31-{y_s}") is False


@given(y=st.integers(min_value=0, max_value=9999))
def test_property_february_boundary(y):
    y_s = f"{y:04d}"
    assert valid_date(f"02-29-{y_s}") is True
    assert valid_date(f"02-30-{y_s}") is False
    assert valid_date(f"02-00-{y_s}") is False


@given(
    m=st.integers(min_value=1, max_value=12),
    y=st.integers(min_value=0, max_value=9999),
)
def test_property_day_zero_always_invalid(m, y):
    s = f"{m:02d}-00-{y:04d}"
    assert reference(s) is False
    assert valid_date(s) is False


@given(m=st.integers(min_value=-50, max_value=50))
def test_property_month_outside_1_to_12_always_invalid(m):
    if 1 <= m <= 12:
        return
    s = f"{m:02d}-15-2000" if -9 <= m <= 99 else "99-15-2000"
    # Build a guaranteed-2-char month field that is out of range when possible
    if 1 <= int(s[:2]) <= 12:
        # fallback: use explicit invalid month strings
        s = "00-15-2000" if m <= 0 else "13-15-2000"
    assert reference(s) is False
    assert valid_date(s) is False


@given(
    m=st.integers(min_value=1, max_value=12),
    d=st.integers(min_value=1, max_value=28),
    y=st.integers(min_value=0, max_value=9999),
)
def test_property_slash_separator_always_invalid(m, d, y):
    s = f"{m:02d}/{d:02d}/{y:04d}"
    assert valid_date(s) is False


@given(s=st.text(alphabet=string.ascii_letters + string.digits + "-/", min_size=0, max_size=12))
def test_property_equivalence_to_reference_model(s):
    assert valid_date(s) == reference(s)
